var TMDbMovieService = class extends TMDbAPIService {
  constructor(settings) {
    super(settings);
    this.adultContent = settings.adult_content;
  }
  async searchMovie(query) {
    const imdbPattern = /^tt\d{7,}$/;
    if (imdbPattern.test(query)) {
      return await this.getMovieByIMDbId(query);
    } else {
      return await this.searchMovieByName(query);
    }
  }
  async getMovieById(id) {
    try {
      return await this.fetchFromTMDb(`/movie/${id.toString()}`);
    } catch (error) {
      if (error instanceof Error && error.message.includes("404")) {
        return null;
      }
      throw error;
    }
  }
  async getMovieByIMDbId(query) {
    let data;
    let movies;
    try {
      data = await this.fetchFromTMDb(`/find/${query}`, {
        external_source: "imdb_id"
      });
      movies = (data.movie_results ?? []).map((raw) => raw);
      return {
        page: 1,
        results: movies,
        total_pages: 1,
        total_results: movies.length
      };
    } catch (error) {
      if (error instanceof Error && error.message.includes("404")) {
        return {
          page: 1,
          results: [],
          total_pages: 1,
          total_results: 0
        };
      }
      throw error;
    }
  }
  async searchMovieByName(query) {
    const data = await this.fetchFromTMDb("/search/movie", {
      query,
      include_adult: String(this.adultContent)
    });
    return data;
  }
};

